import{_ as n,a0 as p,w as d,s as o,I as i,x as a,a1 as l,A as t,ao as h}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"舉例説明 alias 和 unalias 命令 | LCTT x X-CMD","titleTemplate":false,"description":"舉例説明 alias 和 unalias 命令 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"舉例説明 alias 和 unalias 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"舉例説明 alias 和 unalias 命令 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181113 The alias And unalias Commands Explained With Examples","title":"舉例説明 alias 和 unalias 命令","tag":"201811","desc":""},"relativePath":"201811/20181113 The alias And unalias Commands Explained With Examples.md","filePath":"[post].md"}'),r={name:"201811/20181113 The alias And unalias Commands Explained With Examples.md"};function u(g,s,k,b,c,m){const e=p("Link");return d(),o("div",null,[s[28]||(s[28]=i("h1",{id:"舉例説明-alias-和-unalias-命令",tabindex:"-1"},[a("舉例説明 alias 和 unalias 命令 "),i("a",{class:"header-anchor",href:"#舉例説明-alias-和-unalias-命令","aria-label":"Permalink to “舉例説明 alias 和 unalias 命令”"},"​")],-1)),s[29]||(s[29]=i("p",null,[i("img",{src:"https://www.ostechnix.com/wp-content/uploads/2018/11/alias-command-720x340.png",alt:""})],-1)),i("p",null,[s[3]||(s[3]=a("如果不是一個命令列重度用户的話，過了一段時間之後，你就可能已經忘記了這些複雜且冗長的 Linux 命令了。當然，有很多方法可以讓你 ",-1)),l(e,{href:"https://www.ostechnix.com/easily-recall-forgotten-linux-commands/"},{default:t(()=>[...s[0]||(s[0]=[a("回想起遺忘的命令",-1)])]),_:1}),s[4]||(s[4]=a("。你可以簡單的 ",-1)),l(e,{href:"https://www.ostechnix.com/save-commands-terminal-use-demand/"},{default:t(()=>[...s[1]||(s[1]=[a("保存常用的命令",-1)])]),_:1}),s[5]||(s[5]=a(" 然後按需使用。也可以在終端裏 ",-1)),l(e,{href:"https://www.ostechnix.com/bookmark-linux-commands-easier-repeated-invocation/"},{default:t(()=>[...s[2]||(s[2]=[a("標記重要的命令",-1)])]),_:1}),s[6]||(s[6]=a("，然後在任何時候你想要的時間使用它們。而且，Linux 有一個內建命令 ",-1)),s[7]||(s[7]=i("code",null,"history",-1)),s[8]||(s[8]=a(" 可以幫助你記憶這些命令。另外一個記住這些如此長的命令的簡便方式就是為這些命令創建一個別名。你可以為任何經常重複調用的常用命令創建別名，而不僅僅是長命令。通過這種方法，你不必再過多地記憶這些命令。這篇文章中，我們將會在 Linux 環境下舉例説明 ",-1)),s[9]||(s[9]=i("code",null,"alias",-1)),s[10]||(s[10]=a(" 和 ",-1)),s[11]||(s[11]=i("code",null,"unalias",-1)),s[12]||(s[12]=a(" 命令。",-1))]),s[30]||(s[30]=h(`<h3 id="alias-命令" tabindex="-1">alias 命令 <a class="header-anchor" href="#alias-命令" aria-label="Permalink to “alias 命令”">​</a></h3><p><code>alias</code> 使用一個用户自定義的字符串來代替一個或者一串命令（包括多個選項、參數）。這個字符串可以是一個簡單的名字或者縮寫，不管這個命令原來多麼複雜。<code>alias</code> 命令已經預裝在 shell（包括 BASH、Csh、Ksh 和 Zsh 等） 當中。</p><p><code>alias</code> 的通用語法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias [alias-name[=string]...]</span></span></code></pre></div><p>接下來看幾個例子。</p><h4 id="列出別名" tabindex="-1">列出別名 <a class="header-anchor" href="#列出別名" aria-label="Permalink to “列出別名”">​</a></h4><p>可能在你的系統中已經設置了一些別名。有些應用在你安裝它們的時候可能已經自動創建了別名。要查看已經存在的別名，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias</span></span></code></pre></div><p>或者，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias -p</span></span></code></pre></div><p>在我的 Arch Linux 系統中已經設置了下面這些別名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias betty=&#39;/home/sk/betty/main.rb&#39;</span></span>
<span class="line"><span>alias ls=&#39;ls --color=auto&#39;</span></span>
<span class="line"><span>alias pbcopy=&#39;xclip -selection clipboard&#39;</span></span>
<span class="line"><span>alias pbpaste=&#39;xclip -selection clipboard -o&#39;</span></span>
<span class="line"><span>alias update=&#39;newsbeuter -r &amp;&amp; sudo pacman -Syu&#39;</span></span></code></pre></div><h4 id="創建一個新的別名" tabindex="-1">創建一個新的別名 <a class="header-anchor" href="#創建一個新的別名" aria-label="Permalink to “創建一個新的別名”">​</a></h4><p>像我之前説的，你不必去記憶這些又臭又長的命令。你甚至不必一遍一遍的運行長命令。只需要為這些命令創建一個簡單易懂的別名，然後在任何你想使用的時候運行這些別名就可以了。這種方式會讓你愛上命令列。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ du -h --max-depth=1 | sort -hr</span></span></code></pre></div><p>這個命令將會查找當前工作目錄下的各個子目錄佔用的磁盤大小，並按照從大到小的順序進行排序。這個命令有點長。我們可以像下面這樣輕易地為其創建一個 別名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias du=&#39;du -h --max-depth=1 | sort -hr&#39;</span></span></code></pre></div><p>這裏的 <code>du</code> 就是這條命令的別名。這個別名可以被設置為任何名字，主要便於記憶和區別。</p><p>在創建一個別名的時候，使用單引號或者雙引號都是可以的。這兩種方法最後的結果沒有任何區別。</p><p>現在你可以運行這個別名（例如我們這個例子中的 <code>du</code> ）。它和上面的原命令將會產生相同的結果。</p><p>這個別名僅限於當前 shell 會話中。一旦你退出了當前 shell 會話，別名也就失效了。為了讓這些別名長久有效，你需要把它們添加到你 shell 的配置文件當中。</p><p>BASH，編輯 <code>~/.bashrc</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ nano ~/.bashrc</span></span></code></pre></div><p>一行添加一個別名：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/11/alias.png" alt=""></p><p>保存並退出這個文件。然後運行以下命令更新修改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/.bashrc</span></span></code></pre></div><p>現在，這些別名在所有會話中都可以永久使用了。</p><p>ZSH，你需要添加這些別名到 <code>~/.zshrc</code>文件中。Fish，跟上面的類似，添加這些別名到 <code>~/.config/fish/config.fish</code> 文件中。</p><h4 id="查看某個特定的命令別名" tabindex="-1">查看某個特定的命令別名 <a class="header-anchor" href="#查看某個特定的命令別名" aria-label="Permalink to “查看某個特定的命令別名”">​</a></h4><p>像我上面提到的，你可以使用 <code>alias</code> 命令列出你係統中所有的別名。如果你想查看跟給定的別名有關的命令，例如 <code>du</code>，只需要運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias du</span></span>
<span class="line"><span>alias du=&#39;du -h --max-depth=1 | sort -hr&#39;</span></span></code></pre></div><p>像你看到的那樣，上面的命令可以顯示與單詞 <code>du</code> 有關的命令。</p><p>關於 <code>alias</code> 命令更多的細節，參閲 man 手冊頁：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man alias</span></span></code></pre></div><h3 id="unalias-命令" tabindex="-1">unalias 命令 <a class="header-anchor" href="#unalias-命令" aria-label="Permalink to “unalias 命令”">​</a></h3><p>跟它的名字説的一樣，<code>unalias</code> 命令可以很輕鬆地從你的系統當中移除別名。<code>unalias</code> 命令的通用語法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>unalias &lt;alias-name&gt;</span></span></code></pre></div><p>要移除命令的別名，像我們之前創建的 <code>du</code>，只需要運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ unalias du</span></span></code></pre></div><p><code>unalias</code> 命令不僅會從當前會話中移除別名，也會從你的 shell 配置文件中永久地移除別名。</p><p>還有一種移除別名的方法，是創建具有相同名稱的新別名。</p><p>要從當前會話中移除所有的別名，使用 <code>-a</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ unalias -a</span></span></code></pre></div><p>更多細節，參閲 man 手冊頁。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man unalias</span></span></code></pre></div><p>如果你經常一遍又一遍的運行這些繁雜又冗長的命令，給它們創建別名可以節省你的時間。現在是你為常用命令創建別名的時候了。</p><p>這就是所有的內容了。希望可以幫到你。還有更多的乾貨即將到來，敬請期待！</p><p>祝近祺！</p><hr>`,50)),i("p",null,[s[14]||(s[14]=a("via: ",-1)),l(e,{href:"https://www.ostechnix.com/the-alias-and-unalias-commands-explained-with-examples/"},{default:t(()=>[...s[13]||(s[13]=[a("https://www.ostechnix.com/the-alias-and-unalias-commands-explained-with-examples/",-1)])]),_:1})]),i("p",null,[s[19]||(s[19]=a("作者：",-1)),l(e,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[15]||(s[15]=[a("SK",-1)])]),_:1}),s[20]||(s[20]=a(" 選題：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[16]||(s[16]=[a("lujun9972",-1)])]),_:1}),s[21]||(s[21]=a(" 譯者：",-1)),l(e,{href:"https://github.com/dianbanjiu"},{default:t(()=>[...s[17]||(s[17]=[a("dianbanjiu",-1)])]),_:1}),s[22]||(s[22]=a(" 校對：",-1)),l(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[18]||(s[18]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[25]||(s[25]=a("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[23]||(s[23]=[a("LCTT",-1)])]),_:1}),s[26]||(s[26]=a(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:t(()=>[...s[24]||(s[24]=[a("Linux中國",-1)])]),_:1}),s[27]||(s[27]=a(" 榮譽推出",-1))])])}const C=n(r,[["render",u]]);export{y as __pageData,C as default};
